begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
-- Test-runner privilege only; application worker grants do not include extension access.
grant usage on schema extensions to deployreceipt_scan_worker;
create temp table public_test_job(data jsonb);
grant insert,select on public_test_job to deployreceipt_scan_worker;
select ok(not public.public_scan_ready(),'public scanning disabled on fresh install');
select ok((select not operator_enabled and not staging_approved and not production_enabled from public.public_scan_settings),'independent rollout gates default off');
select is(public.public_target_origin('https://www.noviqen.co.uk/path?x=1'),'https://www.noviqen.co.uk','exact canonical origin');
select throws_ok($$select public.public_target_origin('http://2130706433/')$$,'P0001',null,'alternate IP encoding rejected');
select throws_ok($$select public.public_target_origin('https://user:secret@example.com/')$$,'P0001',null,'userinfo rejected');
select throws_ok($$select public.public_target_origin('http://host.local/')$$,'P0001',null,'internal DNS rejected');
select throws_ok($$select public.public_target_origin('https://example.com:444/')$$,'P0001',null,'nondefault port rejected');
insert into auth.users(id,email,email_confirmed_at) values('75111111-1111-4111-8111-111111111111','public-owner@example.test',now()),('75222222-2222-4222-8222-222222222222','worker@example.test',now());
insert into auth.sessions(id,user_id)values('76111111-1111-4111-8111-111111111111','75111111-1111-4111-8111-111111111111'),('76222222-2222-4222-8222-222222222222','75222222-2222-4222-8222-222222222222');
insert into public.beta_access(email)values('public-owner@example.test');
insert into public.scan_worker_identities values('75222222-2222-4222-8222-222222222222',true);
select is(public.scan_worker_access_token('{"user_id":"75222222-2222-4222-8222-222222222222","claims":{"role":"authenticated"}}')->'claims'->>'role','deployreceipt_scan_worker','only registered worker gets dedicated role');
select is(public.scan_worker_access_token('{"user_id":"75111111-1111-4111-8111-111111111111","claims":{"role":"authenticated"}}')->'claims'->>'role','authenticated','ordinary member cannot acquire worker role');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"75111111-1111-4111-8111-111111111111","role":"authenticated","session_id":"76111111-1111-4111-8111-111111111111"}',true);
insert into public.projects(name,website_url)values('public test','https://www.noviqen.co.uk/');
select throws_ok($$select public.request_public_scan((select id from public.projects where name='public test'),true)$$,'P0001','public_scanning_unavailable','member cannot bypass default operator gate');
select throws_ok($$select public.request_public_scan((select id from public.projects where name='public test'),false)$$,'P0001','explicit_consent_required','consent required');
select throws_ok($$select * from public.public_scan_settings$$,'42501',null,'member cannot read/change operator configuration');
select throws_ok($$select public.scan_worker_access_token('{}')$$,'42501',null,'token hook not a role escalation RPC');
select throws_ok($$select public.public_worker_attest(true,'public-gateway-v1')$$,'42501',null,'member cannot forge infrastructure heartbeat');
select throws_ok($$select public.lease_scan_job()$$,'42501',null,'member cannot lease jobs');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.scan_settings set mode='public';
update public.beta_settings set environment='staging',enforced=true,scanning_enabled=true;
update public.public_scan_settings set operator_enabled=true,staging_approved=true,infrastructure_checked_at=now(),security_suite_sha=repeat('a',40);
insert into public.domain_verifications(project_id,domain,status,method,verified_at,expires_at)select id,'www.noviqen.co.uk','verified','dns',now(),now()+interval '1 hour' from public.projects where name='public test';
set local role deployreceipt_scan_worker;
select set_config('request.jwt.claims','{"sub":"75222222-2222-4222-8222-222222222222","role":"deployreceipt_scan_worker","session_id":"76222222-2222-4222-8222-222222222222"}',true);
select ok(public.public_worker_attest(true,'public-gateway-v1'),'dedicated active worker can attest bounded readiness');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"75111111-1111-4111-8111-111111111111","role":"authenticated","session_id":"76111111-1111-4111-8111-111111111111"}',true);
select ok(public.public_scanning_status(),'member sees only ready approved staging public mode');
select throws_ok($$select public.request_scan((select id from public.projects where name='public test'))$$,'P0001','explicit_consent_required','old fixture API cannot silently run public scans');
select lives_ok($$select public.request_public_scan((select id from public.projects where name='public test'),true)$$,'verified owner can submit bounded consented public job');
select throws_ok($$select public.request_public_scan((select id from public.projects where name='public test'),true)$$,'P0001','public_worker_busy','global concurrency serializes accounts');
set local role deployreceipt_scan_worker;
select set_config('request.jwt.claims','{"sub":"75222222-2222-4222-8222-222222222222","role":"deployreceipt_scan_worker","session_id":"76222222-2222-4222-8222-222222222222"}',true);
insert into pg_temp.public_test_job select public.lease_scan_job();
select is((select data->>'kind' from pg_temp.public_test_job),'scan','dedicated worker can lease consented verified public job');
select ok(public.worker_artifact_allowed((select (data->'run'->>'id')||'/1/desktop.png' from pg_temp.public_test_job),false),'worker artifact upload bound to its current run/attempt');
select ok(not public.worker_artifact_allowed(gen_random_uuid()::text||'/1/desktop.png',false),'worker cannot upload to another run');
select ok(public.record_scan_configuration((select(data->'run'->>'id')::uuid from pg_temp.public_test_job),(select(data->>'lease')::uuid from pg_temp.public_test_job),'{"mode":"public","transport":"pinned_gateway_v1"}'),'configuration records the executed public transport');
select ok(public.finish_scan((select(data->'run'->>'id')::uuid from pg_temp.public_test_job),(select(data->>'lease')::uuid from pg_temp.public_test_job),'timed_out','[]'),'assigned worker can persist incomplete diagnostic result without inventing observations');
select ok(not public.worker_artifact_allowed((select (data->'run'->>'id')||'/1/desktop.png' from pg_temp.public_test_job),false),'finished lease cannot upload new evidence');
select throws_ok($$select * from public.projects$$,'42501',null,'worker cannot read customer project tables');
select throws_ok($$select * from public.scan_checks$$,'42501',null,'worker cannot read customer observations');
select throws_ok($$select public.request_public_scan(gen_random_uuid(),true)$$,'42501',null,'worker cannot submit customer scans');
select throws_ok($$select public.finish_scan(gen_random_uuid(),gen_random_uuid(),'completed','[]')$$,'42501',null,'worker cannot finish another job');
select throws_ok($$select public.internal_finish_scan(gen_random_uuid(),gen_random_uuid(),'completed','[]')$$,'42501',null,'internal service functions are not worker bypasses');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.public_scan_settings set infrastructure_checked_at=now()-interval '25 hours';
select ok(not public.public_scan_ready(),'expired independent infrastructure check fails closed');
update public.public_scan_settings set infrastructure_checked_at=now(),production_enabled=true;
select ok(not public.public_scan_ready(),'production switch cannot activate staging public mode');
update public.public_scan_settings set production_enabled=false;
update public.scan_worker_identities set active=false;
set local role deployreceipt_scan_worker;
select set_config('request.jwt.claims','{"sub":"75222222-2222-4222-8222-222222222222","role":"deployreceipt_scan_worker","session_id":"76222222-2222-4222-8222-222222222222"}',true);
select throws_ok($$select public.public_worker_attest(true,'public-gateway-v1')$$,'42501','not_authorized','revoked worker JWT immediately loses privileges');
reset role;
select * from finish();rollback;
